<form method="post" enctype="multipart/form-data" action="<?= $product?'/admin/products/'.$product['id'].'/edit':'/admin/products/create' ?>"><?= App\Core\Csrf::field() ?><div class="row"><div class="col-lg-8"><section class="panel"><h2>Thông tin sản phẩm</h2><?php foreach(['name'=>'Tên sản phẩm','sku'=>'SKU','slug'=>'Slug (chữ thường, số, dấu gạch ngang)'] as $name=>$label):?><label class="form-label" for="product-<?= $name ?>"><?= $label ?></label><input class="form-control" name="<?= $name ?>" id="product-<?= $name ?>" value="<?= e($product[$name]??'') ?>" required><?php endforeach?><label class="form-label" for="product-description">Mô tả</label><textarea class="form-control" name="description" id="product-description" rows="6"><?= e($product['description']??'') ?></textarea><label class="form-label" for="product-price">Giá bán (VND)</label><input class="form-control" name="price" id="product-price" type="number" min="0" step="1" value="<?= e($product['price']??0) ?>" required></section><section class="panel"><h2>Thông số kỹ thuật</h2><div id="spec-fields"><?php foreach($product['specs']??[['spec_key'=>'','spec_value'=>'']] as $s):?><div class="d-flex gap-2 mb-2"><input class="form-control" name="spec_keys[]" value="<?= e($s['spec_key']) ?>" aria-label="Tên thông số" placeholder="Tên thông số"><input class="form-control" name="spec_values[]" value="<?= e($s['spec_value']) ?>" aria-label="Giá trị thông số" placeholder="Giá trị"></div><?php endforeach?></div><button id="add-spec" class="btn btn-light mt-2" type="button">+ Thêm thông số</button><p class="small muted mt-2">Xóa tên thông số để bỏ dòng khi lưu.</p></section></div><div class="col-lg-4"><section class="panel"><h2>Phân loại & tồn kho</h2><label class="form-label" for="product-category">Danh mục</label><select class="form-select" id="product-category" name="category_id"><?php foreach($categories as $c):?><option value="<?= $c['id'] ?>" <?= ($product['category_id']??0)==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach?></select><label class="form-label" for="product-brand">Thương hiệu</label><select class="form-select" id="product-brand" name="brand_id"><?php foreach($brands as $b):?><option value="<?= $b['id'] ?>" <?= ($product['brand_id']??0)==$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select><label class="form-label" for="product-min">Ngưỡng tồn tối thiểu</label><input type="number" class="form-control" id="product-min" name="min_stock" min="0" value="<?= e($product['min_stock']??5) ?>"><p class="small muted mt-3">Tồn hiện tại: <?= $product['stock']??0 ?>. Nhập/xuất bằng phiếu kho để bảo toàn lịch sử.</p><label class="d-block my-2"><input type="checkbox" name="is_active" value="1" <?= !$product||$product['is_active']?'checked':'' ?>> Đang bán</label><label class="d-block my-2"><input type="checkbox" name="is_featured" value="1" <?= $product&&$product['is_featured']?'checked':'' ?>> Sản phẩm nổi bật</label></section><section class="panel"><h2>Ảnh sản phẩm</h2><p class="small muted">JPEG, PNG, WebP; tối đa 8 ảnh/lần, 5 MB/ảnh.</p><input class="form-control" type="file" id="product-images" name="images[]" accept="image/jpeg,image/png,image/webp" multiple><div class="d-flex flex-wrap gap-2 mt-3"><?php foreach($product['images']??[] as $image):?><label><img class="thumb d-block" src="<?= e($image['path']) ?>" alt="Ảnh sản phẩm"><small><input type="checkbox" name="remove_images[]" value="<?= $image['id'] ?>"> Xóa ảnh</small></label><?php endforeach?></div></section><button id="save-product" class="btn btn-primary w-100" type="submit">Lưu sản phẩm</button></div></div></form>
